-- Ref: .teos/schemas/MIGRATION-ORDER.md #6, .teos/sections/04,
-- .teos/conventions/adapter-manifest-format.md
-- Command registry rows. builtin/custom load from YAML at boot and
-- upsert here; discovered rows are generated by --help parsing. An id
-- claimed by a higher-priority source leaves the lower row shadowed
-- (shadowed_by set), not deleted — custom work survives a builtin
-- takeover.
CREATE TABLE command_manifests (
    id            TEXT NOT NULL,                   -- dotted namespaced: docker.container.logs
    source        TEXT NOT NULL DEFAULT 'builtin', -- builtin | custom | discovered
    application   TEXT NOT NULL,                   -- owning CLI
    name          TEXT NOT NULL,                   -- human label (palette/context UI)
    description   TEXT NOT NULL DEFAULT '',
    params        TEXT NOT NULL DEFAULT '[]',      -- JSON array of parameter defs
    executable    TEXT NOT NULL,
    arguments     TEXT NOT NULL DEFAULT '[]',      -- JSON array; "{param}" template refs
    risk          TEXT NOT NULL DEFAULT 'informational',
    confirmation  INTEGER NOT NULL DEFAULT 0,      -- broker confirm required (risk ≥ controlled)
    timeout_s     INTEGER NOT NULL DEFAULT 0,
    working_dir   TEXT NOT NULL DEFAULT '',        -- template refs allowed: "{session.cwd}"
    ctx_processes TEXT NOT NULL DEFAULT '[]',      -- JSON array: context.processes
    ctx_files     TEXT NOT NULL DEFAULT '[]',      -- JSON array: context.files
    tags          TEXT NOT NULL DEFAULT '[]',
    shadowed_by   TEXT,                            -- winning manifest id when this row loses
    enabled       INTEGER NOT NULL DEFAULT 1,
    created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    PRIMARY KEY (id, source)                       -- same id may exist once per source
);
CREATE INDEX idx_manifests_app ON command_manifests(application);
